# Every play is core: each one runs on every covered stock and gets its own page there.
# The 20 below are the ones a newcomer should learn first (the "20 plays to learn first"
# article): the most widely taught and followed rule from each corner of technical trading.
STARTER_SLUGS = [
    "200-day-rule", "golden-cross", "ten-month-sma", "stage-analysis", "trend-template", "ichimoku-cloud",
    "parabolic-sar", "macd-signal-cross", "four-week-rule", "turtle-system-2", "bollinger-breakout",
    "time-series-momentum", "dual-momentum", "52-week-high", "rsi-30-70", "rsi-2-pullback", "stochastic-20-80",
    "on-balance-volume", "halloween-indicator", "supertrend",
]
for _p in PLAYS:
    _p["core"] = not _p.get("benchmark")
    _p["starter"] = _p["slug"] in STARTER_SLUGS

PLAY = {p["slug"]: p for p in PLAYS}
TIMED = [p for p in PLAYS if not p.get("benchmark")]
STARTER = [next(p for p in TIMED if p["slug"] == s) for s in STARTER_SLUGS]
assert len(STARTER) == 20
BAR_WORD = {"D": "daily", "W": "weekly", "M": "month-end"}


def by_family():
    return [(k, FAMILY[k][0], [p for p in TIMED if p["family"] == k]) for k in FAMILY_ORDER]
